async function processNextJob() {
  // Atomically move job from 'pending' to 'processing'
  const job = await redis.lMove('jobs:pending', 'jobs:processing', 'LEFT', 'RIGHT');
  if (!job) return;

  try {
    await doWork(job);
    // On success, remove from processing
    await redis.lRem('jobs:processing', 1, job);
  } catch (err) {
    // On failure, put back in pending
    await redis.lMove('jobs:processing', 'jobs:pending', 'LEFT', 'LEFT');
    throw err;
  }
}

// Recover lost jobs (e.g. on startup)
const stuck = await redis.lRange('jobs:processing', 0, -1);
for (const job of stuck) {
  await redis.lMove('jobs:processing', 'jobs:pending', 'LEFT', 'LEFT');
}

// Follow a user
async function follow(userId, targetId) {
  await redis.sAdd(`user:${userId}:following`, targetId);
  await redis.sAdd(`user:${targetId}:followers`, userId);
}

// Get mutual friends
async function getMutualFriends(userId1, userId2) {
  return redis.sInter(
    `user:${userId1}:following`,
    `user:${userId2}:following`
  );
}

// Who to suggest following (friends of friends minus already following)
async function getSuggestions(userId) {
  const following = await redis.sMembers(`user:${userId}:following`);
  const friendsOfFriends = `user:${userId}:suggestions:temp`;

  for (const friendId of following) {
    await redis.sUnionStore(friendsOfFriends, friendsOfFriends, `user:${friendId}:following`);
  }

  const suggestions = await redis.sDiff(friendsOfFriends, `user:${userId}:following`);
  await redis.del(friendsOfFriends);
  return suggestions.filter(id => id !== userId);
}
